def seed(apps, schema_editor):
    Category=apps.get_model('home','PriceCategory'); Item=apps.get_model('home','PriceItem')
    if Category.objects.exists(): return
    for section,categories in DATA.items():
        for c_order,(title,subtitle,items) in enumerate(categories,1):
            cat=Category.objects.create(section=section,title=title,subtitle=subtitle,order=c_order,is_active=True)
            for order,(code,name,price,price_text) in enumerate(items,1):
                Item.objects.create(category=cat,code=code,name=name,price=price,price_text=price_text,order=order,is_active=True)

def unseed(apps, schema_editor):
    apps.get_model('home','PriceCategory').objects.all().delete()

